	router.GET(options.BaseURL+"/bookmarks", wrapper.ListBookmarks, options.OperationMiddlewares["listBookmarks"]...)
	router.POST(options.BaseURL+"/bookmarks", wrapper.CreateBookmark, options.OperationMiddlewares["createBookmark"]...)
