// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// DeleteAccount Permanently erase all of the user's app data
	// (DELETE /account)
	DeleteAccount(ctx context.Context, request DeleteAccountRequestObject) (DeleteAccountResponseObject, error)
	// AuthCallback IdP redirect target
	// (GET /auth/callback)
	AuthCallback(ctx context.Context, request AuthCallbackRequestObject) (AuthCallbackResponseObject, error)
	// AuthLogin Start the IdP login
	// (GET /auth/login)
	AuthLogin(ctx context.Context, request AuthLoginRequestObject) (AuthLoginResponseObject, error)
	// AuthLogout End the session
	// (POST /auth/logout)
	AuthLogout(ctx context.Context, request AuthLogoutRequestObject) (AuthLogoutResponseObject, error)
	// ListBookmarks List or search bookmarks, or list the trash
	// (GET /bookmarks)
	ListBookmarks(ctx context.Context, request ListBookmarksRequestObject) (ListBookmarksResponseObject, error)
	// CreateBookmark Save a URL as a bookmark
	// (POST /bookmarks)
	CreateBookmark(ctx context.Context, request CreateBookmarkRequestObject) (CreateBookmarkResponseObject, error)
	// DeleteBookmark Move a bookmark to the trash
	// (DELETE /bookmarks/{id})
	DeleteBookmark(ctx context.Context, request DeleteBookmarkRequestObject) (DeleteBookmarkResponseObject, error)
	// GetBookmark Get one bookmark with its page content
	// (GET /bookmarks/{id})
	GetBookmark(ctx context.Context, request GetBookmarkRequestObject) (GetBookmarkResponseObject, error)
	// UpdateBookmark Edit user-defined fields of a bookmark
	// (PATCH /bookmarks/{id})
	UpdateBookmark(ctx context.Context, request UpdateBookmarkRequestObject) (UpdateBookmarkResponseObject, error)
	// RestoreBookmark Restore a trashed bookmark to root
	// (POST /bookmarks/{id}/restore)
	RestoreBookmark(ctx context.Context, request RestoreBookmarkRequestObject) (RestoreBookmarkResponseObject, error)
	// GetFavicon Get stored favicon bytes
	// (GET /favicons/{id})
	GetFavicon(ctx context.Context, request GetFaviconRequestObject) (GetFaviconResponseObject, error)
	// ListFolders List every folder as a flat list
	// (GET /folders)
	ListFolders(ctx context.Context, request ListFoldersRequestObject) (ListFoldersResponseObject, error)
	// CreateFolder Create a folder
	// (POST /folders)
	CreateFolder(ctx context.Context, request CreateFolderRequestObject) (CreateFolderResponseObject, error)
	// DeleteFolder Permanently delete a folder and its subtree
	// (DELETE /folders/{id})
	DeleteFolder(ctx context.Context, request DeleteFolderRequestObject) (DeleteFolderResponseObject, error)
	// UpdateFolder Rename or move a folder with its contents
	// (PATCH /folders/{id})
	UpdateFolder(ctx context.Context, request UpdateFolderRequestObject) (UpdateFolderResponseObject, error)
	// GetSyncVersion Get the user's change counter
	// (GET /sync/version)
	GetSyncVersion(ctx context.Context, request GetSyncVersionRequestObject) (GetSyncVersionResponseObject, error)
	// EmptyTrash Permanently delete every trashed bookmark
	// (DELETE /trash)
	EmptyTrash(ctx context.Context, request EmptyTrashRequestObject) (EmptyTrashResponseObject, error)
}

